{
  "decision-wayfinding-sign-export-after-walkthrough": "WITH replacements AS (SELECT o.site_code, o.required_text, o.order_id, c.check_id FROM sign_order AS o JOIN field_check AS c ON c.site_code = o.site_code WHERE c.seen_text IS NULL OR c.seen_text COLLATE BINARY <> o.required_text ORDER BY o.site_code COLLATE BINARY ASC) SELECT group_concat(order_id, ',') AS order_id_set, group_concat(check_id, ',') AS check_id_set, 'site_code,required_text,order_id,check_id' || char(10) || group_concat('\"' || replace(site_code, '\"', '\"\"') || '\",\"' || replace(required_text, '\"', '\"\"') || '\",\"' || replace(order_id, '\"', '\"\"') || '\",\"' || replace(check_id, '\"', '\"\"') || '\"' || char(10), '') AS csv_content FROM replacements",
  "decision-wheel-state-at-shutter-open": "SELECT f.frame_id, w.filter_code, w.source_id FROM frames AS f LEFT JOIN wheel_notes AS w ON (w.event_s, w.seq_no) = (SELECT n.event_s, n.seq_no FROM wheel_notes AS n WHERE n.event_kind = 'seated' AND n.event_s <= f.shutter_s ORDER BY n.event_s DESC, n.seq_no DESC LIMIT 1) ORDER BY f.frame_id ASC"
}
